import json
import ast
import re
from typing import List, Tuple, Optional

def perceive(observation_history: list[str]) -> str:
    """
    Parse the latest raw observation and return a concise text summary of
    decision-relevant features (<2000 chars).  Never raises, never returns empty.
    """
    obs = observation_history[-1]   # current observation
    grid = None                     # will become list of lists (int or str)

    # ------------------------------------------------------------------
    # 1. Try to extract the grid in either encoding
    # ------------------------------------------------------------------
    try:
        # ---- ARC integer grid ----
        if '<grid_' in obs:
            lines = obs.splitlines()
            grid_start = None
            for i, line in enumerate(lines):
                if line.strip().startswith('<grid_'):
                    grid_start = i
                    break
            if grid_start is not None:
                rows = []
                for line in lines[grid_start + 1:]:
                    stripped = line.strip()
                    if not stripped:
                        continue
                    if stripped.startswith('[') and stripped.endswith(']'):
                        row = ast.literal_eval(stripped)
                        rows.append(row)
                    elif stripped.startswith('<grid_'):
                        break   # stop at next grid marker
                if rows:
                    grid = rows
        # ---- Autumn string grid (JSON 2D array) ----
        else:
            start = obs.find('[[')
            end = obs.rfind(']]')
            if start != -1 and end != -1:
                json_str = obs[start:end + 2]
                grid = json.loads(json_str)
    except Exception:
        grid = None

    # ------------------------------------------------------------------
    # 2. Fallback if parsing failed
    # ------------------------------------------------------------------
    if not grid:
        return "agent:(0,0);objects:[]"

    # ------------------------------------------------------------------
    # 3. Helper: colour string for a given cell
    # ------------------------------------------------------------------
    # Palette for integer grid
    INT_PALETTE = {
        0: 'black', 1: 'blue', 2: 'red', 3: 'green',
        4: 'yellow', 5: 'light-gray', 6: 'magenta',
        7: 'orange', 8: 'light-blue', 9: 'dark-red',
        10: 'white', 11: 'dark-gray'
    }
    # Colours that are likely agent markers (unique moving objects)
    AGENT_CANDIDATES = {'blue', 'red', 'green', 'yellow', 'magenta',
                        'orange', 'light-blue', 'white'}

    def cell_colour(cell) -> str:
        if isinstance(cell, int):
            return INT_PALETTE.get(cell, 'unknown')
        else:
            return cell.lower()

    # ------------------------------------------------------------------
    # 4. Count occurrences of each colour and build list of all non‑black cells
    # ------------------------------------------------------------------
    colour_count = {}
    all_cells = []   # list of (row, col, colour)
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            col = cell_colour(cell)
            if col == 'black':
                continue
            colour_count[col] = colour_count.get(col, 0) + 1
            all_cells.append((r, c, col))

    # ------------------------------------------------------------------
    # 5. Identify agent position
    # ------------------------------------------------------------------
    agent_pos = None
    # a) prefer a colour from AGENT_CANDIDATES with count == 1
    for colour in AGENT_CANDIDATES:
        if colour_count.get(colour) == 1:
            for r, c, col in all_cells:
                if col == colour:
                    agent_pos = (r, c)
                    break
            break
    # b) fall back to any colour that appears exactly once (excluding black)
    if agent_pos is None:
        for col, cnt in colour_count.items():
            if cnt == 1:
                for r, c, col2 in all_cells:
                    if col2 == col:
                        agent_pos = (r, c)
                        break
                break
    # c) last resort: use the first non‑black cell
    if agent_pos is None and all_cells:
        agent_pos = all_cells[0][:2]

    # If we still have nothing (only black cells) use (0,0)
    if agent_pos is None:
        agent_pos = (0, 0)

    # ------------------------------------------------------------------
    # 6. Build list of non‑black cells that are NOT the agent
    # ------------------------------------------------------------------
    objects = []
    for r, c, col in all_cells:
        if (r, c) == agent_pos:
            continue
        objects.append((r, c, col))

    # ------------------------------------------------------------------
    # 7. Construct the output string (<2000 chars)
    # ------------------------------------------------------------------
    agent_str = f"agent:({agent_pos[0]},{agent_pos[1]})"
    obj_items = []
    for r, c, col in objects:
        obj_items.append(f"({r},{c},{col})")
    obj_str = ";".join(obj_items)
    # Truncate objects if the total would exceed the limit
    max_total = 2000
    # Reserve space for the agent part and separators
    base = agent_str + ";objects:["
    remaining = max_total - len(base) - 1  # closing ']'
    if len(obj_str) > remaining:
        obj_str = obj_str[:remaining] + "..."
    result = f"{base}{obj_str}]"

    # Final safety: never return empty
    if not result.strip():
        result = "agent:(0,0);objects:[]"
    return result

