    AGENT_CANDIDATES = {'blue', 'red', 'green', 'yellow', 'magenta',
                        'orange', 'light-blue', 'white'}

    def cell_colour(cell) -> str:
        if isinstance(cell, int):
            return INT_PALETTE.get(cell, 'unknown')
        else:
            return cell.lower()

