    # 4. Count occurrences of each colour and build list of all non‑black cells
    # ------------------------------------------------------------------
    colour_count = {}
    all_cells = []   # list of (row, col, colour)
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            col = cell_colour(cell)
            if col == 'black':
