    pattern = r"(?:Action taken|Last action)\s*:\s*click\s+(\d+)\s+(\d+)"
    for hist_obs in reversed(observation_history):
        matches = re.findall(pattern, hist_obs, re.IGNORECASE)
        if matches:
            # Use the last match (most recent)
