    for r, c, col in all_cells:
        if (r, c) == agent_pos or (r, c) == cursor_pos:
            continue
        objects.append((r, c, col))

    # ------------------------------------------------------------------
    # 8. Sort objects by row then column for determinism
    # ------------------------------------------------------------------
    objects.sort(key=lambda x: (x[0], x[1]))

